  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'השמעה, הערות, לייקים, צפייה מאוחרת יותר, מנויים, התראות, הודעות, רשימות השמעה והגדרות שפה זמינים דרך תפריט הניווט הראשי וחשבון.',
  'PlayHub' => 'PlayHub',
  'PlayHub is a video platform for uploading, watching, scheduling, managing, and moderating creator content from one account.' => 'PlayHub היא פלטפורמת וידאו להעלאה, צפייה, תזמון, ניהול וניהול תוכן של יוצרים מחשבון אחד.',
  'PlayHub is the video platform running on this deployment, built for creators, viewers, communities, and platform operators.' => 'PlayHub היא פלטפורמת הווידאו הפועלת בפריסה זו, שנבנתה עבור יוצרים, צופים, קהילות ומפעילי פלטפורמה.',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.' => 'PlayHub מספקת ערוצי יוצרים, העלאות סרטונים, פרסום מתוזמן, מינויים, תגובות, רשימות השמעה, צפייה מאוחרת יותר, דפי תוכן חי וכלי ניהול מפלטפורמה אחת.',
  'PlayHub uses essential cookies and browser storage for login sessions, API authentication, CSRF/security behavior, language selection, theme selection, account menu state, and other features required for the application to work.' => 'PlayHub משתמש בקובצי Cookie חיוניים ואחסון דפדפן עבור הפעלות התחברות, אימות API, התנהגות CSRF/אבטחה, בחירת שפה, בחירת ערכת נושא, מצב תפריט החשבון ותכונות אחרות הנדרשות כדי שהאפליקציה תעבוד.',
