  'Review privacy and cookie details for this deployment.' => 'סקור פרטי פרטיות וקובצי Cookie עבור פריסה זו.',
  'Rules for using this PlayHub deployment as a viewer, creator, or administrator.' => 'כללים לשימוש בפריסה זו של PlayHub כצופה, יוצר או כמנהל.',
  'Safety' => 'בטיחות',
