  'Scheduled video release and reminders.' => 'פרסום סרטון מתוזמן ותזכורות.',
  'Scheduled videos' => 'סרטונים מתוזמנים',
  'Scheduling a video release' => 'תזמון פרסום וידאו',
  'Search for answers...' => 'חפש תשובות...',
  'Search help articles, topics, or questions...' => 'חפש מאמרי עזרה, נושאים או שאלות...',
  'Select a reason' => 'בחר סיבה',
  'Select one or more video files, enter required details, choose category and language, add a thumbnail, choose visibility, and publish. Large files are uploaded in chunks before the server starts processing.' => 'בחר קובץ וידאו אחד או יותר, הזן את הפרטים הנדרשים, בחר קטגוריה ושפה, הוסף תמונה ממוזערת, בחר נראות ופרסם. קבצים גדולים מועלים בחתיכות לפני שהשרת מתחיל לעבד.',
  'Send a message and it will be saved for admins.' => 'שלח הודעה והיא תישמר למנהלים.',
  'Send billing details to admin support for review.' => 'שלח פרטי חיוב לתמיכת מנהל המערכת לבדיקה.',
  'Send message' => 'שלח הודעה',
  'Send order details through the refund popup.' => 'שלח פרטי הזמנה דרך החלון הקופץ להחזר.',
  'Send us a message' => 'שלחו לנו הודעה',
