  'session, token' => 'מושב, אסימון',
  'Settings and login' => 'הגדרות וכניסה',
  'Short summary' => 'סיכום קצר',
  'Sign in and use Settings for account, profile, password, notification, privacy, and creator preferences. Creator upload and content issues should include the video title, channel, browser, and any processing error shown on the upload page.' => 'היכנס והשתמש בהגדרות עבור חשבון, פרופיל, סיסמה, הודעה, פרטיות והעדפות יוצר. בעיות העלאה ותוכן של יוצרים צריכות לכלול את כותרת הסרטון, הערוץ, הדפדפן וכל שגיאת עיבוד המוצגת בדף ההעלאה.',
  'Sign in for account support' => 'היכנס לתמיכה בחשבון',
  'Signed in' => 'מחובר',
  'Start uploading' => 'התחל להעלות',
  'Still can’t find an answer?' => 'עדיין לא מוצאים תשובה?',
  'Stored for admins' => 'מאוחסן עבור מנהלי מערכת',
  'Stores language, theme, and interface preferences.' => 'מאחסן העדפות שפה, ערכת נושא וממשק.',
  'Studio, playlists, analytics, channels.' => 'סטודיו, פלייליסטים, אנליטיקס, ערוצים.',
  'Submit a billing or refund message to admin support.' => 'שלח הודעת חיוב או החזר כספי לתמיכת מנהל המערכת.',
  'Submit refund request' => 'שלח בקשה להחזר',
  'Submit request' => 'שלח בקשה',
  'Subscription cancellation' => 'ביטול מנוי',
  'Support dashboard' => 'תמיכה בלוח המחוונים',
  'System status' => 'מצב המערכת',
  'Table' => 'טבלה',
  'Taxonomies' => 'טקסונומיות',
  'Technical issue' => 'בעיה טכנית',
  'Technical notes for integrations with the current PlayHub API and upload workflow.' => 'הערות טכניות לאינטגרציות עם ה-API הנוכחי של PlayHub וזרימת עבודה להעלאה.',
  'Tell us more about your question or request...' => 'ספר לנו עוד על השאלה או הבקשה שלך...',
  'Terms of Use' => 'תנאי שימוש',
  'The configured' => 'המוגדר',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'עמוד המפתחים מחובר ל-backend החי של Laravel: מלאי נתיב, ספירת מסד נתונים, מגבלות העלאה ומטא נתונים של הפלטפורמה נטענים מ-/api/developers.',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'החזית מאחסנת העדפות כמו שפה נבחרה, ערכת נושא, תור השמעה, התקדמות הצפייה ומצב הממשק, כך שהחוויה נשארת עקבית לאורך ניווט הדפים והטעינות מחדש.',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'עבודת העיבוד מקודדת עיבודים, יוצרת תמונות ממוזערות בעת הצורך, מאחסנת כתוביות ומסמנת סרטונים מוכנים עם סיום העיבוד. סרטונים מתוכננים עתידיים נשארים פרטיים עד שהמתזמן ישחרר אותם.',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'מערכת ההעלאה מגובה במסד נתונים, תומכת בקטגוריות ובשפות מהממשק ה-API, מעבדת סרטונים שהועלו, מאחסנת תמונות ממוזערות וכיתובים ושומרת על תוכן מתוכנן פרטי עד למועד שחרורו.',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'דף זה מסביר כיצד PlayHub משתמש בקובצי Cookie ואחסון דפדפן עבור הפעלות, אבטחה, העדפות, השמעה ותכונות מאומתות.',
  'Ticket source' => 'מקור כרטיס',
  'Top content categories' => 'קטגוריות תוכן מובילות',
  'Topic' => 'נושא',
  'Transaction / invoice' => 'עסקה / חשבונית',
  'Transaction / invoice ID' => 'מזהה עסקה / חשבונית',
  'Unable to send message.' => 'לא ניתן לשלוח הודעה.',
  'Unable to submit refund request.' => 'לא ניתן להגיש בקשה להחזר.',
  'Understanding admin support tickets' => 'הבנת כרטיסי תמיכת מנהל',
  'Upload and processing help' => 'עזרה בהעלאה ועיבוד',
  'Upload chunks' => 'העלה נתחים',
  'Upload issues' => 'בעיות בהעלאה',
  'Upload languages' => 'העלה שפות',
  'Upload limit' => 'מגבלת העלאה',
  'Upload options' => 'אפשרויות העלאה',
  'Upload or processing' => 'העלאה או עיבוד',
  'Upload page' => 'עמוד העלאה',
  'Upload pipeline' => 'העלאת צינור',
  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'העלה, צפה, הירשם, נהל ובנה עם נתוני PlayHub חיים.',
  'Uploaded videos' => 'סרטונים שהועלו',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'סרטונים שהועלו מקודדים לביצועים שניתנים להפעלה. זמן העיבוד תלוי בגודל הקובץ, משך הזמן, עומס השרת ומצב התור. דף ההעלאה וסטודיו ליוצרים מציגים סטטוס עיבוד אמיתי מתקליט הווידאו.',
  'Uploads, scheduling, and processing are available.' => 'העלאות, תזמון ועיבוד זמינים.',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => 'השתמש ב-/api/videos, בנקודות קצה של ערוץ ובמסלולים מאומתים עבור תהליכי עבודה של יוצרים.',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'השתמש בפעולות דיווח מובנות עבור סרטונים והערות כדי שמנהלי מערכת יקבלו את ההפניה המדויקת לתוכן. דפי לוח המחוונים של מנהל המערכת משתמשים בנתוני מסד נתונים חיים עבור משתמשים, תוכן, דוחות, מונטיזציה, ניתוח, תמיכה, תפקידים והגדרות מערכת.',
  'Use Contact Us' => 'השתמש צור קשר',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'השתמש ב-JSON עבור בקשות API רגילות וב-FormData עבור העלאות קבצים. אל תעקוף אימות: קטגוריות ושפות הם מזהי מסד נתונים, החשיפה מוגבלת לציבור, לא רשום או פרטי, והכתוביות מקבלים קובצי SRT, VTT או TXT.',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'השתמש בהגדרות כדי לעדכן את הפרופיל שלך, אבטחה, סיסמה, מסירה דו-גורמית, מכשירים, העדפות ואפשרויות התראות. אם אינך יכול לגשת לחשבון שלך, השתמש בזרימת הכניסה וספק את הדוא"ל של החשבון למנהל האתר.',
  'Use the contact form' => 'השתמש בטופס צור קשר',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'השתמש בפעולות הדיווח על סרטונים, תגובות ופוסטים בקהילה כדי שמנהלי מערכת יקבלו את ההפניה המדויקת לתוכן.',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'השתמש בפעולות הדיווח על סרטונים, תגובות ופוסטים בקהילה כאשר תוכן עשוי להפר את כללי הפלטפורמה. דוחות אלו קשורים לרשומת התוכן האמיתית והם טובים יותר מהודעה כללית מכיוון שמנהלי מערכת יכולים לסקור את הפריט המדויק.',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'השתמש בערוץ PlayHub הנכון עבור עזרה בחשבון, דוחות תוכן, בעיות טכניות ובקשות מנהל.',
  'Video categories' => 'קטגוריות וידאו',
  'Video for everyone. Built for creators and viewers.' => 'סרטון לכולם. נבנה מנתוני פלטפורמה אמיתיים.',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'בעיות בהעלאת וידאו, תזמון, תמונות ממוזערות ועיבוד.',
  'Videos, thumbnails, captions, processing.' => 'סרטונים, תמונות ממוזערות, כיתובים, עיבוד.',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'הצופים יכולים לעיין בקטגוריות, לחפש סרטונים, לצפות בתוכן, להירשם לערוצים, לשמור סרטונים לצפייה מאוחר יותר, להגיב, לקבל התראות ולנהל העדפות שפה ונגישות.',
  'Viewing and community help' => 'צפייה ועזרה קהילתית',
  'Waiting for backend endpoint inventory.' => 'ממתין למלאי של נקודות קצה אחורי.',
  'We’re here to help.' => 'אנחנו כאן כדי לעזור.',
  'What is PlayHub?' => 'מה זה PlayHub?',
  'What PlayHub does' => 'מה PlayHub עושה',
  'Where do contact messages go?' => 'לאן עוברות הודעות יצירת קשר?',
  'Why is my video still processing?' => 'מדוע הסרטון שלי עדיין מעובד?',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'כֵּן. השתמש בשדה התאריך והשעה המקוריים של לוח הזמנים בדף ההעלאה. הקצה האחורי מאחסן את scheduled_at, מעבד את הסרטון, שומר אותו פרטי בזמן שהתאריך הוא בעתיד, ומשחרר אותו כאשר מתזמן Laravel פועל לאחר השעה המתוכננת.',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'כֵּן. השתמש בשדה התזמון המקורי בהעלאה. הקצה האחורי מאחסן את scheduled_at ומשחרר את הסרטון לאחר עיבוד כאשר מועד התזמון מגיע.',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'אתה גולש כאורח. היכנס כדי לגשת לכלים ספציפיים לחשבון.',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'אתה אחראי לאישורי החשבון שלך, לפעילות הפרופיל, לתוכן שהועלה, להערות, להודעות ולכל פעולות יוצר או מנהל שבוצעו מהחשבון שלך. השתמש בסיסמאות חזקות ושמור על שיטות מסירה דו-גורמיות עדכניות.',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'אתה יכול לנקות קובצי Cookie של דפדפן ואחסון מקומי בהגדרות הדפדפן שלך. ניקוי אחסון חיוני עשוי להוציא אותך מהחשבון, לאפס את העדפות השפה/נושא, להסיר את מצב ההשמעה המקומי ולדרוש ממך להיכנס שוב.',
  'You receive a response by email.' => 'אתה מקבל תשובה במייל.',
  'You’re in control' => 'אתה בשליטה',
  'Your choices' => 'הבחירות שלך',
  'Your message is saved directly in the website backend and appears in the admin dashboard under Support.' => 'ההודעה שלך נשמרת ישירות בקצה העורפי של האתר ומופיעה בלוח המחוונים לניהול תחת תמיכה.',
  'Your support' => 'התמיכה שלך',
  'Watch video' => 'צפה בסרטון',
  'Copy link' => 'העתק קישור',
  'View creator' => 'צפה ביוצר',
  'Remove from playlist' => 'הסר מרשימת ההשמעה',
  'Removing videos from playlists is not available here yet.' => 'הסרת סרטונים מפלייליסטים אינה זמינה כאן עדיין.',
  'Create New Playlist' => 'צור רשימת השמעה חדשה',
  'Organize your videos into a playlist' => 'ארגן את הסרטונים שלך לרשימת השמעה',
  'Playlist Name' => 'שם רשימת השמעה',
  'e.g. Travel Vlogs 2025' => 'למשל וולוגים לנסיעות 2025',
  '(optional)' => '(אופציונלי)',
