  'Select Color' => 'בחר צבע',
  'This color will represent your playlist' => 'צבע זה ייצג את רשימת ההשמעה שלך',
  'Anyone can view this playlist' => 'כל אחד יכול לצפות בפלייליסט הזה',
  'Only you can view this playlist' => 'רק אתה יכול להציג את הפלייליסט הזה',
  'Anyone with the link can view' => 'כל מי שיש לו את הקישור יכול לצפות',
  'Add to Playlist' => 'הוסף לפלייליסט',
  'Add videos to this playlist now' => 'הוסף סרטונים לפלייליסט הזה עכשיו',
