  'Clear' => 'ברור',
  'Tip' => 'טיפ',
  'Use playlists to organize your content and make it easier for your audience to discover more videos.' => 'השתמש בפלייליסטים כדי לארגן את התוכן שלך ולהקל על הקהל שלך לגלות סרטונים נוספים.',
  'Unable to create playlist.' => 'לא ניתן ליצור רשימת השמעה.',
