  'Create your first playlist to organize videos from your channel and saved library.' => 'צור את הפלייליסט הראשון שלך כדי לארגן סרטונים מהערוץ ומהספרייה השמורה שלך.',
  'Loading playlists...' => 'טוען רשימות השמעה...',
