  'About this playlist' => 'על הפלייליסט הזה',
  'This playlist belongs to your PlayHub account.' => 'רשימת השמעה זו משתמשת ברשומות רשימות השמעה אמיתיות מחשבון PlayHub שלך.',
  'Playlist stats' => 'נתונים סטטיסטיים של רשימת השמעה',
